insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_music1_v1'
from (values
('117.310.c.1.A',2,'A student listens to a recording of a professional wind ensemble and then attends a live school concert to compare. She is exploring what?','["Exemplary musical examples through technology and live performance", "Ticket pricing", "Stage lighting wiring", "Parking rules"]'::jsonb,0,'Both recordings and live concerts provide models.','original'),
('117.310.c.1.A',2,'Why do musicians listen to exemplary recordings?','["To avoid practicing", "To hear a model of tone, style and phrasing", "To skip rehearsals", "To memorize the cover art"]'::jsonb,1,'Models guide musical choices.','original'),
('117.310.c.1.B',2,'While listening to a choir piece, a student hears a tune on top and supporting notes below. The tune is the ___ part.','["Percussive only", "Silent", "Melodic", "Rhythmic only"]'::jsonb,2,'The melody is the main tune; harmony supports it.','original'),
('117.310.c.1.B',2,'Notes sounded together to support a melody form what?','["Rest", "Tempo", "Meter", "Harmony"]'::jsonb,3,'Harmony is simultaneous pitches.','original'),
('117.310.c.1.C',2,'The distance in pitch between two notes is called a(n) what?','["Interval", "Cadenza", "Measure", "Fermata"]'::jsonb,0,'An interval measures pitch distance.','original'),
('117.310.c.1.C',2,'A chord built from a root, a third and a fifth is called a what?','["Tie", "Triad", "Scale", "Rest"]'::jsonb,1,'A triad stacks thirds.','original'),
('117.310.c.1.D',2,'In 4/4 time, how many beats are in each measure?','["Six", "Three", "Four", "Two"]'::jsonb,2,'The top number shows beats per measure.','original'),
('117.310.c.1.D',2,'What does meter organize in music?','["Voices into parts", "Notes into chords", "Pitches into scales", "Beats into groups with strong and weak pulses"]'::jsonb,3,'Meter groups the steady beat.','original'),
('117.310.c.1.E',2,'Which of these is an element of music?','["Rhythm", "Choreography", "Brushstroke", "Set design"]'::jsonb,0,'Rhythm, melody, harmony and form are musical elements.','original'),
('117.310.c.1.E',2,'A sign such as crescendo or ritardando is an example of what?','["A clef", "An expression marking", "A time signature", "A key signature"]'::jsonb,1,'Expression markings shape performance.','original'),
('117.310.c.1.F',2,'Which habit best protects a musician''s hearing?','["Turning volume up louder", "Ignoring ringing in the ears", "Using hearing protection and limiting time near loud sound", "Playing at maximum loudness daily"]'::jsonb,2,'Hearing loss from loud sound is preventable.','original'),
('117.310.c.1.F',2,'Good posture while practicing helps a musician avoid what?','["Counting rhythms", "Hearing pitch", "Reading notes", "Tension and strain injuries"]'::jsonb,3,'Healthy body mechanics prevent strain.','original'),
('117.310.c.2.A',3,'Which meter is a compound meter?','["6/8", "3/8", "2/4", "4/4"]'::jsonb,0,'Compound meter divides the beat into three.','original'),
('117.310.c.2.A',3,'Meter that mixes groups of two and three beats, such as 5/8, is called what?','["Even", "Asymmetrical", "Silent", "Simple"]'::jsonb,1,'Asymmetrical meters have uneven groupings.','original'),
('117.310.c.2.B',2,'The Italian term piano tells a performer to play how?','["Slowly", "Fast", "Softly", "Loudly"]'::jsonb,2,'Piano means soft.','original'),
('117.310.c.2.B',2,'A dot placed above or below a note head tells a player to do what?','["Play it louder", "Skip it", "Hold it long", "Play it short and detached"]'::jsonb,3,'A dot indicates staccato.','original'),
('117.310.c.3.A',3,'A mature, characteristic sound on a trumpet should be what?','["Full, centered and appropriate to the style", "Unfocused", "Thin and airy", "Always as loud as possible"]'::jsonb,0,'Tone quality fits the instrument and genre.','original'),
('117.310.c.3.A',3,'What most helps a singer produce a mature choral tone?','["Shouting", "Supported breath and tall vowels", "A tight throat", "Shallow breaths"]'::jsonb,1,'Breath support and vowel shape build tone.','original'),
('117.310.c.3.B',3,'Which is an example of a psychomotor skill in performance?','["Choosing a seat", "Reading the program", "Using correct posture and hand position", "Buying a ticket"]'::jsonb,2,'Physical technique is psychomotor.','original'),
('117.310.c.3.B',3,'Breathing deeply from the diaphragm helps a performer do what?','["Play without notes", "Skip counting", "Avoid dynamics", "Sustain phrases with steady air"]'::jsonb,3,'Air control supports phrasing.','original'),
('117.310.c.3.C',3,'A player who keeps a steady beat with a metronome is demonstrating what?','["Rhythmic accuracy at the right tempo", "Random pitch", "Poor timing", "Loud dynamics"]'::jsonb,0,'Steady pulse shows accuracy.','original'),
('117.310.c.3.C',3,'A student rushes during an easy passage. What should she fix?','["The program title", "Her steadiness of tempo", "The key signature", "The seating"]'::jsonb,1,'Rushing is a tempo-control issue.','original'),
('117.310.c.3.D',3,'A piece has two sharps in its key signature. A player should do what?','["Ignore the sharps", "Play every note flat", "Play F-sharp and C-sharp unless marked otherwise", "Play only naturals"]'::jsonb,2,'Key signature applies to all notes of those names.','original'),
('117.310.c.3.D',3,'The modality of a piece, such as major or minor, affects what?','["The length of rests", "The stage size", "The ticket price", "The scale pattern and mood of the music"]'::jsonb,3,'Mode sets the interval pattern.','original'),
('117.310.c.3.E',3,'A note that sounds slightly flat to the ensemble has a problem with what?','["Intonation", "Articulation", "Rhythm", "Meter"]'::jsonb,0,'Intonation is accuracy of pitch.','original'),
('117.310.c.3.E',3,'Shaping a phrase with a gradual crescendo then decrescendo uses what?','["A key change", "Appropriate dynamics and phrasing", "Silence only", "Wrong notes"]'::jsonb,1,'Dynamics shape musical lines.','original'),
('117.310.c.3.F',3,'A student writes a four-measure melody and records it on her phone. She is doing what?','["Buying music", "Tuning an instrument", "Creating and recording an original musical phrase", "Copying a score"]'::jsonb,2,'Composition can be notated or recorded.','original'),
('117.310.c.3.F',3,'Which tool can notate an original phrase?','["A calculator", "A thermometer", "A ruler only", "Music notation software"]'::jsonb,3,'Notation software records musical ideas.','original'),
('117.310.c.4.A',3,'Sight reading with a mature sound means a player should do what even on a new piece?','["Keep tone quality steady while reading unfamiliar music", "Stop and restart repeatedly", "Skip hard measures", "Play only loudly"]'::jsonb,0,'Tone should not suffer.','original'),
('117.310.c.4.A',3,'Which statement describes good sight-reading tone?','["Always thin", "Characteristic of the genre despite unfamiliar notes", "Never supported", "Different in every measure"]'::jsonb,1,'Tone stays consistent.','original'),
('117.310.c.4.B',3,'While sight reading, a violinist keeps her bow arm relaxed and her posture balanced. She is demonstrating what?','["Audience etiquette", "Program notes", "Psychomotor and kinesthetic skills", "Music theory only"]'::jsonb,2,'Physical technique carries into reading.','original'),
('117.310.c.4.B',3,'A singer sight reading takes a quiet, quick breath at a rest. She is using what?','["Silence the whole piece", "Random sounds", "Transposition", "Planned breathing"]'::jsonb,3,'Breathing is planned at rests.','original'),
('117.310.c.4.C',3,'Before sight reading, a student scans the time signature and counts a measure aloud. Why?','["To establish rhythmic accuracy using a counting system", "To avoid the key", "To find the composer''s birthday", "To check the page color"]'::jsonb,0,'Counting systems support accuracy.','original'),
('117.310.c.4.C',3,'What should a sight reader do if she makes a rhythm error?','["Walk away", "Keep the beat going and continue", "Change the tempo wildly", "Stop the whole group"]'::jsonb,1,'Staying in time matters.','original'),
('117.310.c.4.D',3,'A sight-reading player notices one flat in the key signature. Which note is flat?','["C", "G", "B", "F"]'::jsonb,2,'One flat is B-flat.','original'),
('117.310.c.4.D',3,'Why check the key signature before sight reading?','["To choose a seat", "To see the title", "To count measures", "To know which notes are sharped or flatted throughout"]'::jsonb,3,'The key signature affects many notes.','original'),
('117.310.c.4.E',3,'Singing do, re, mi while reading a melody uses what system?','["Solfège", "Time signature", "Fingering chart", "Chord tab"]'::jsonb,0,'Solfège names scale degrees.','original'),
('117.310.c.4.E',3,'Reading a melody by singing numbers like 1, 2, 3 for scale degrees is an example of what?','["A rest", "A melodic reading system", "A tuning method", "A rhythm exercise"]'::jsonb,1,'Numbers can label scale degrees.','original'),
('117.310.c.4.F',3,'A sight reader listens and adjusts her pitch to match the group. She is working on what?','["Notation", "Tempo", "Intonation", "Meter"]'::jsonb,2,'Listening improves pitch matching.','original'),
('117.310.c.4.F',3,'While sight reading, following written dynamics shows what?','["Poor focus", "Missing the rhythm", "No phrasing", "Appropriate dynamics"]'::jsonb,3,'Dynamics are part of the score.','original'),
('117.310.c.5.A',3,'A student compares a Baroque fugue with a modern jazz piece. She is comparing music by what?','["Genre, style and historical period", "Instrument color", "Ticket cost", "Seat location"]'::jsonb,0,'Comparison covers style and era.','original'),
('117.310.c.5.A',3,'Which pair differs mainly by culture?','["Two measures", "Mariachi and Irish folk music", "Two identical scales", "Two quarter notes"]'::jsonb,1,'Regional traditions differ by culture.','original'),
('117.310.c.5.B',2,'Which is a music-related career?','["Plumber", "Pilot", "Sound engineer", "Surveyor"]'::jsonb,2,'Audio engineering is a music career.','original'),
('117.310.c.5.B',2,'A person who plays in a community band on weekends has a music what?','["Degree", "License", "Vocation", "Avocation"]'::jsonb,3,'An avocation is a hobby pursuit.','original'),
('117.310.c.5.C',2,'A lullaby sung to calm a baby shows music used for what?','["Comfort and nurturing in a culture", "Weather reports", "Math tests", "Selling cars"]'::jsonb,0,'Music serves social purposes.','original'),
('117.310.c.5.C',2,'Why is music played at many ceremonies?','["It solves equations", "It marks and expresses important events", "It replaces speech laws", "It cooks food"]'::jsonb,1,'Ceremonies use music to express meaning.','original'),
('117.310.c.5.D',3,'Counting fractions of a beat in rhythm most closely connects music to which subject?','["Typing", "Cooking", "Mathematics", "Gym"]'::jsonb,2,'Rhythm uses fractions.','original'),
('117.310.c.5.D',3,'Studying how sound waves travel connects music to what discipline?','["Geography only", "History only", "Painting only", "Physics"]'::jsonb,3,'Acoustics is physics.','original'),
('117.310.c.5.E',3,'Downloading music without paying the artist raises what issue?','["Ethical and economic issues about creators'' rights", "A tuning issue", "A rhythm issue", "A key signature issue"]'::jsonb,0,'Artists deserve compensation.','original'),
('117.310.c.5.E',3,'How have streaming services changed music?','["They removed melody", "They changed how listeners access music and how artists earn money", "They ended all live music", "They made instruments unnecessary"]'::jsonb,1,'Technology reshaped the business.','original'),
('117.310.c.5.F',3,'A student builds a digital portfolio of recordings to apply for a music program. She is using what?','["A time signature", "A tuner only", "Tools for college and career preparation", "A rest symbol"]'::jsonb,2,'Portfolios support applications.','original'),
('117.310.c.5.F',3,'A musician posts performance clips to promote herself. She is using what?','["A conductor''s baton", "A metronome", "A staff", "Social media as a career tool"]'::jsonb,3,'Social media can build an audience.','original'),
('117.310.c.6.A',2,'At a formal concert, when should audience members applaud?','["At the end of a piece or when the conductor signals", "During quiet passages", "Whenever they like", "Between every movement loudly"]'::jsonb,0,'Etiquette respects the music.','original'),
('117.310.c.6.A',2,'As a performer, proper concert etiquette includes what?','["Talking during the piece", "Entering and leaving the stage calmly and respectfully", "Leaving mid-song", "Checking a phone onstage"]'::jsonb,1,'Performers show professionalism.','original'),
('117.310.c.6.B',3,'A class creates a rubric listing tone, rhythm, intonation and expression to judge a recording. This is what?','["Ignoring quality", "Guessing", "Designing criteria for informed judgments", "Copying a score"]'::jsonb,2,'Criteria support judgments.','original'),
('117.310.c.6.B',3,'Which judgment is informed?','["No comment", "I just liked it", "It was fine", "The balance was good but the tenors were sharp in measure 12"]'::jsonb,3,'Specific evidence makes judgments useful.','original'),
('117.310.c.6.C',3,'A student records herself weekly and tracks progress on a chart. She is developing what?','["A process for self-evaluation", "A ticket system", "A seating chart", "A concert program"]'::jsonb,0,'Tracking supports improvement.','original'),
('117.310.c.6.C',3,'Which tool helps a musician evaluate her own playing?','["A calendar only", "A recording with a checklist", "A map", "A mirror only"]'::jsonb,1,'Recordings reveal details.','original'),
('117.310.c.6.D',3,'A student compares her ensemble''s recording with a professional recording. She is doing what?','["Changing the key", "Avoiding feedback", "Evaluating a performance against an exemplary model", "Skipping the recording"]'::jsonb,2,'Models set standards.','original'),
('117.310.c.6.D',3,'After comparing to a model, what is the best next step?','["Blame the instrument", "Quit practicing", "Ignore the model", "Choose specific areas to improve and practice them"]'::jsonb,3,'Evaluation should lead to action.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
